{
  "name": "@opentj/opencode-oauth2-plugin",
  "version": "1.0.4",
  "description": "OpenCode OAuth2 认证插件，支持太极 SSO 单点登录",
  "type": "module",
  "main": "./dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./package.json": "./package.json"
  },
  "sideEffects": false,
  "files": [
    "dist",
    "package.json"
  ],
  "scripts": {
    "build": "tsc && node -e \"const fs=require('fs');fs.copyFileSync('.oauth2-config.json','dist/.oauth2-config.json');fs.copyFileSync('package.json','dist/package.json')\"",
    "dev": "tsx index.ts",
    "test": "node --experimental-vm-modules node_modules/jest/bin/jest.js",
    "lint": "tsc --noEmit",
    "prepublishOnly": "tsc"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.14.48",
    "open": "^11.0.0"
  },
  "devDependencies": {
    "@jest/globals": "^29.7.0",
    "@types/node": "^20.0.0",
    "jest": "^29.7.0",
    "ts-jest": "^29.4.9",
    "tsx": "^4.7.0",
    "typescript": "^5.3.0"
  },
  "engines": {
    "node": ">=18.0.0"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "oauth2",
    "oauth2-authentication",
    "taiji",
    "sso",
    "authentication",
    "plugin"
  ],
  "repository": {
    "type": "git",
    "url": "https://github.com/opentj/opencode-oauth2-plugin"
  },
  "bugs": {
    "url": "https://github.com/opentj/opencode-oauth2-plugin/issues"
  },
  "homepage": "https://github.com/opentj/opencode-oauth2-plugin#readme",
  "author": "Taiji",
  "license": "MIT",
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org/"
  }
}

